begin;
set local search_path=public,extensions;
select no_plan();
create temp table identity_fx(key text primary key,value jsonb);
insert into identity_fx(key,value)select key,to_jsonb(gen_random_uuid())from unnest(array['admin','admin_session','staff','staff_session','namespace','namespace2','package','package2','product'])key;
insert into auth.users(id,email,raw_user_meta_data)select(value#>>'{}')::uuid,'identity-'||(value#>>'{}')||'@example.test','{}'from identity_fx where key in('admin','staff');
update profiles set is_active=true,full_name='Synthetic identity reviewer'where id in(select(value#>>'{}')::uuid from identity_fx where key in('admin','staff'));
insert into user_roles(user_id,role)select(value#>>'{}')::uuid,'ADMIN'from identity_fx where key='admin'on conflict do nothing;
insert into user_roles(user_id,role)select(value#>>'{}')::uuid,'STAFF'from identity_fx where key='staff'on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)select(value#>>'{}')::uuid,(select(value#>>'{}')::uuid from identity_fx where key=replace(s.key,'_session','')),now(),now()from identity_fx s where key in('admin_session','staff_session');
create function pg_temp.identity_id(k text)returns uuid language sql as $$select(value#>>'{}')::uuid from identity_fx where key=k$$;
create function pg_temp.claim_identity(k text,claim_role text default 'authenticated')returns void language plpgsql as $$begin
 perform set_config('request.jwt.claims',jsonb_build_object('role',claim_role,'sub',pg_temp.identity_id(k),'session_id',pg_temp.identity_id(k||'_session'))::text,true);
end $$;
create function pg_temp.identity_packet(k text,definition jsonb,expected integer default null)returns jsonb language sql as $$
 select jsonb_build_object('id',pg_temp.identity_id(k),'expected_version',expected,'definition',definition,'review_note','Synthetic SQL metadata review','attest_review',true)
$$;
create function pg_temp.identity_apply(k text,op text,packet jsonb)returns jsonb language plpgsql as $$declare action uuid:=gen_random_uuid();result jsonb;begin
 perform public.prepare_inventory_identity_review(pg_temp.identity_id('admin'),action,op,packet);
 result:=public.execute_inventory_identity_review(pg_temp.identity_id('admin'),action);
 set constraints all immediate;set constraints all deferred;
 insert into identity_fx values(k,jsonb_build_object('action',action,'receipt',result,'packet',packet));return result;
end $$;
select pg_temp.claim_identity('admin');
select create_inventory_product(pg_temp.identity_id('product'),'Synthetic ten mg/mL','medication','Synthetic manufacturer','mL',100);
select ok(relrowsecurity,'Private identity RLS: '||relname)from pg_class where relnamespace='public'::regnamespace and relname in('inventory_identity_entries','inventory_identity_reviews','inventory_identity_versions','inventory_identity_bindings','inventory_identity_actions','inventory_identity_cancellations');
select ok(not has_table_privilege(role,relation,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'Direct identity access denied: '||role||'/'||relation)
from unnest(array['anon','authenticated','service_role'])role cross join unnest(array['inventory_identity_entries','inventory_identity_reviews','inventory_identity_versions','inventory_identity_bindings','inventory_identity_actions','inventory_identity_cancellations'])relation;
select ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE')and has_function_privilege('authenticated',oid,'EXECUTE'),'Guarded identity RPC grant: '||proname)from pg_proc where pronamespace='public'::regnamespace and proname in('prepare_inventory_identity_review','read_inventory_identity_review','execute_inventory_identity_review','cancel_inventory_identity_review','list_inventory_identities','read_inventory_identity','lookup_inventory_identifier');
select ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),'Private identity helper: '||proname)from pg_proc where pronamespace='public'::regnamespace and proname like 'inventory_identity_%';
select throws_ok($$select inventory_identity_gtin('036000291453')$$,'23514','GTIN check digit invalid','GTIN checksum enforced');
select throws_ok($$select inventory_identity_uuid('"AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA"')$$,'23514','Canonical nonzero inventory identity required','Canonical machine UUID prevents mismatched receipt spelling');
select is(inventory_identity_gtin('036000291452'),'00036000291452','GTIN leading zeros and normalized scope');
select throws_ok($$select inventory_identity_gtin('00000000000000')$$,'23514','Valid GTIN digits required','Unassigned zero code rejected');
select throws_ok($$select inventory_identity_conversion('{"stock_units_numerator":"1e3","purchase_units_denominator":"1"}')$$,'23514','Positive bounded conversion terms required','No conversion exponent/float coercion');
select throws_ok($$select inventory_identity_conversion('{"stock_units_numerator":"1000000000001","purchase_units_denominator":"1"}')$$,'23514','Positive bounded conversion terms required','Conversion term ceiling enforced');
select lives_ok($$select inventory_identity_conversion('{"stock_units_numerator":"1","purchase_units_denominator":"1000"}')$$,'Fractional ratio stored exactly');
select throws_ok($$select inventory_identity_text(to_jsonb(E'00012\t'::text),200)$$,'23514','Clean bounded identity text required','SKU control characters rejected');
select is(inventory_identity_text('"000012-A"',200),'000012-A','Text SKU zeros and case preserved');
select pg_temp.identity_apply('ns_saved','namespace',pg_temp.identity_packet('namespace','{"supplier":"mwi","account_label":"Synthetic MWI account","catalog_scope":"Synthetic list","active":true}'));
select pg_temp.identity_apply('ns2_saved','namespace',pg_temp.identity_packet('namespace2','{"supplier":"midwest","account_label":"Synthetic Midwest account","catalog_scope":"Synthetic list","active":true}'));
create function pg_temp.package_definition(ns_key text,ratio text default '10',include_gtin boolean default true)returns jsonb language sql as $$
 select jsonb_build_object('product_id',pg_temp.identity_id('product'),'product_version',1,'stock_unit','mL','label','Synthetic package','manufacturer','Synthetic manufacturer','strength','10mg/mL','form','injectable','purchase_unit','vial','conversion',jsonb_build_object('stock_units_numerator',ratio,'purchase_units_denominator','1'),'active',true,'identifiers',jsonb_build_array(jsonb_build_object('kind','supplier_sku','namespace_id',pg_temp.identity_id(ns_key),'namespace_version_id',(select head_id from inventory_identity_entries where id=pg_temp.identity_id(ns_key)),'value','000123','raw_source','000123'))||case when include_gtin then jsonb_build_array(jsonb_build_object('kind','gtin','namespace_id',null,'namespace_version_id',null,'value','00036000291452','raw_source','036000291452'))else'[]'::jsonb end)
$$;
select pg_temp.identity_apply('package_saved','package',pg_temp.identity_packet('package',pg_temp.package_definition('namespace')));
select is((select count(*)from inventory_identity_versions),3::bigint,'Two namespace versions and one package');
select is((lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace'))->'items'->0->>'id'),pg_temp.identity_id('package')::text,'Namespace scoped lookup resolves package');
select is((lookup_inventory_identifier('gtin','00036000291452')->'items'->0->>'id'),pg_temp.identity_id('package')::text,'Reviewed manufacturer GTIN lookup resolves same package');
select is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace2'))->'items'),0,'Identical unassigned SKU in another supplier is not the same');
select is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000124')->'items'),0,'Unknown SKU never creates a product');
select pg_temp.identity_apply('package2_saved','package',pg_temp.identity_packet('package2',pg_temp.package_definition('namespace2','20',false)));
select is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000123')->'items'),2,'Unscoped supplier SKU has explicit multiple candidates');
select is((lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace2'))->'items'->0#>>'{definition,conversion,stock_units_numerator}'),'20','Different reviewed package size preserved');
select is(execute_inventory_identity_review(pg_temp.identity_id('admin'),(select(value->>'action')::uuid from identity_fx where key='package_saved')),(select value->'receipt'from identity_fx where key='package_saved'),'Same UUID returns exact original receipt');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('admin'),(select(value->>'action')::uuid from identity_fx where key='package_saved'),'namespace',(select value->'packet'from identity_fx where key='package_saved'))$$,'23505','Inventory review UUID is immutable','Changed operation cannot reuse original UUID');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('staff'),gen_random_uuid(),'namespace',(select value->'packet'from identity_fx where key='ns_saved'))$$,'42501','Matched inventory reviewer required','Actor parameter must match session');
select pg_temp.identity_apply('ns_retired','namespace',pg_temp.identity_packet('namespace','{"supplier":"mwi","account_label":"Synthetic MWI account","catalog_scope":"Synthetic list","active":false}',1));
select is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace'))->'items'),0,'Retired supplier namespace immediately ineligible');
select is(jsonb_array_length(lookup_inventory_identifier('gtin','00036000291452')->'items'),1,'Manufacturer package identifier is independent of supplier retirement');
select pg_temp.identity_apply('ns_reactivated','namespace',pg_temp.identity_packet('namespace','{"supplier":"mwi","account_label":"Synthetic MWI account","catalog_scope":"Synthetic list","active":true}',2));
select is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace'))->'items'),0,'Reactivation does not silently restore stale bindings');
select pg_temp.identity_apply('package_updated','package',pg_temp.identity_packet('package',pg_temp.package_definition('namespace','12'),1));
select is((lookup_inventory_identifier('supplier_sku','000123',pg_temp.identity_id('namespace'))->'items'->0#>>'{definition,conversion,stock_units_numerator}'),'12','Explicit package re-review restores exact new namespace version');
select is(execute_inventory_identity_review(pg_temp.identity_id('admin'),(select(value->>'action')::uuid from identity_fx where key='package_saved')),(select value->'receipt'from identity_fx where key='package_saved'),'Later changes do not alter original receipt');
select is((read_inventory_identity(pg_temp.identity_id('package'),null,1)->>'next')::integer,2,'Bounded history exposes next version cursor');
select is(jsonb_array_length(read_inventory_identity(pg_temp.identity_id('package'),2,1)->'history'),1,'Next history page retrieves original immutable version');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('admin'),gen_random_uuid(),'package',(select value->'packet'from identity_fx where key='package_saved'))$$,'PT409','Inventory mapping changed; review current version','Stale expected package version rejected');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('admin'),gen_random_uuid(),'namespace',pg_temp.identity_packet('namespace','{"supplier":"midwest","account_label":"Synthetic MWI account","catalog_scope":"Synthetic list","active":true}',3))$$,'23514','New namespace required for a different supplier account/catalog','Supplier identity cannot be repurposed');
select throws_ok($$update inventory_identity_versions set definition='{}'where entry_id=pg_temp.identity_id('package')$$,'23514','Inventory identity evidence is immutable','Published mapping history cannot mutate');
select throws_ok($$delete from inventory_identity_actions where id=(select(value->>'action')::uuid from identity_fx where key='package_saved')$$,'23514','Inventory identity evidence is immutable','Saved receipt cannot be deleted');
select throws_ok($$truncate inventory_identity_reviews cascade$$,'23514','Inventory identity evidence is immutable','Review history cannot be truncated');
select throws_ok($$update inventory_identity_entries set product_id=gen_random_uuid()where id=pg_temp.identity_id('package')$$,'23514','Inventory identity is immutable; revise its reviewed version','Package cannot be redirected to another clinical product');
select throws_ok($$insert into inventory_identity_bindings(kind,namespace_key,namespace_version_id,value,package_id,package_version_id)select'supplier_barcode',pg_temp.identity_id('namespace'),n.head_id,'ROGUE',p.id,p.head_id from inventory_identity_entries n,inventory_identity_entries p where n.id=pg_temp.identity_id('namespace')and p.id=pg_temp.identity_id('package');set constraints all immediate$$,'23514','Exact active package identifier projection required','Raw owner binding must match immutable approved definition');
set constraints all deferred;

insert into identity_fx values('collision_package',to_jsonb(gen_random_uuid())),('collision_action',to_jsonb(gen_random_uuid()));
select prepare_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'),'package',pg_temp.identity_packet('collision_package',pg_temp.package_definition('namespace2','25')));
select throws_ok($$select execute_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'))$$,'23505',null,'Conflicting global GTIN cannot remap another package');
select is((select count(*)from inventory_identity_entries where id=pg_temp.identity_id('collision_package')),0::bigint,'Identifier collision rolls back newly created package');
select is((select count(*)from inventory_identity_actions where id=pg_temp.identity_id('collision_action')),0::bigint,'Failed collision cannot invent saved receipt');
select is((read_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'))->>'state'),'prepared','Failed execution recovers original prepared UUID');
select cancel_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'));
select is(read_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'))->>'state','cancelled','Explicit cancellation closes prepared failed attempt');
select throws_ok($$select execute_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('collision_action'))$$,'PT409','Inventory review expired/cancelled;recover saved work','Cancelled action cannot later save');
select is(cancel_inventory_identity_review(pg_temp.identity_id('admin'),(select(value->>'action')::uuid from identity_fx where key='package_saved'))->'receipt',(select value->'receipt'from identity_fx where key='package_saved'),'Cancellation after save returns original committed receipt');
insert into identity_fx values('cancel_missing',to_jsonb(gen_random_uuid()));
select cancel_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('cancel_missing'));
select is(read_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('cancel_missing'))->>'state','cancelled','Missing preparation has an owned durable closed outcome');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('cancel_missing'),'namespace',jsonb_build_object('id',gen_random_uuid(),'expected_version',null,'definition',jsonb_build_object('supplier','mwi','account_label','Synthetic cancellation','catalog_scope','list','active',false),'review_note','Synthetic cancellation','attest_review',true))$$,'PT409','Inventory action cancelled;check saved work','Late preparation cannot resurrect cancellation');
insert into identity_fx values('expired_action',to_jsonb(gen_random_uuid()));
insert into inventory_identity_reviews(id,actor_id,session_id,operation,request,created_at,expires_at)values(pg_temp.identity_id('expired_action'),pg_temp.identity_id('admin'),pg_temp.identity_id('admin_session'),'namespace',jsonb_build_object('id',gen_random_uuid(),'expected_version',null,'definition',jsonb_build_object('supplier','mwi','account_label','Synthetic expired','catalog_scope','list','active',false),'review_note','Synthetic expired','attest_review',true),clock_timestamp()-interval'20 minutes',clock_timestamp()-interval'5 minutes');
select is(read_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('expired_action'))->>'state','expired','Expired preparation recovers as expired');
select throws_ok($$select execute_inventory_identity_review(pg_temp.identity_id('admin'),pg_temp.identity_id('expired_action'))$$,'PT409','Inventory review expired/cancelled;recover saved work','Expired preparation cannot publish');
do $$declare i integer;begin for i in 1..32 loop
 perform prepare_inventory_identity_review(pg_temp.identity_id('admin'),gen_random_uuid(),'namespace',jsonb_build_object('id',gen_random_uuid(),'expected_version',null,'definition',jsonb_build_object('supplier','mwi','account_label','Synthetic quota '||i,'catalog_scope','list','active',false),'review_note','Synthetic quota review','attest_review',true));
end loop;end $$;
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('admin'),gen_random_uuid(),'namespace',jsonb_build_object('id',gen_random_uuid(),'expected_version',null,'definition',jsonb_build_object('supplier','mwi','account_label','Synthetic quota excess','catalog_scope','list','active',false),'review_note','Synthetic quota excess','attest_review',true))$$,'23514','Check pending inventory reviews first','Pending review quota is enforced');
select is((select count(*)from inventory_identity_reviews r where actor_id=pg_temp.identity_id('admin')and expires_at>clock_timestamp()and not exists(select 1 from inventory_identity_actions a where a.id=r.id)and not exists(select 1 from inventory_identity_cancellations c where c.id=r.id)),32::bigint,'No extra review after quota rejection');
update auth.sessions set not_after=clock_timestamp()-interval'1 second'where id=pg_temp.identity_id('admin_session');
select throws_ok($$select list_inventory_identities('namespace')$$,'42501','Current staff session required for reviewed drafts','Expired actual session row cannot read metadata');
update auth.sessions set not_after=null where id=pg_temp.identity_id('admin_session');
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=false where id=pg_temp.identity_id('admin');
select pg_temp.claim_identity('admin');
select throws_ok($$select list_inventory_identities('namespace')$$,'42501','Active staff access required','Deactivated reviewer cannot read metadata');
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=true where id=pg_temp.identity_id('admin');
select pg_temp.claim_identity('admin');

select pg_temp.claim_identity('staff');
select is(jsonb_array_length(list_inventory_identities('namespace')->'items'),2,'Staff can read reviewed metadata');
select throws_ok($$select prepare_inventory_identity_review(pg_temp.identity_id('staff'),gen_random_uuid(),'namespace',(select value->'packet'from identity_fx where key='ns_saved'))$$,'42501','Active veterinarian or administrator required','Staff cannot publish package/namespace');
select throws_ok($$select read_inventory_identity_review(pg_temp.identity_id('staff'),(select(value->>'action')::uuid from identity_fx where key='package_saved'))$$,'42501','Inventory review belongs to another account','Staff cannot recover another actor prepared action');
select pg_temp.claim_identity('admin','service_role');
select throws_ok($$select list_inventory_identities('namespace')$$,'42501','Authenticated staff required','Service identity cannot impersonate clinical staff');
select pg_temp.claim_identity('admin');
set local timezone='America/Denver';
select is(inventory_identity_view(pg_temp.identity_id('package')),(select value->'receipt'->'entry'from identity_fx where key='package_updated'),'Current audit projection is caller-timezone independent');
select ok((inventory_identity_view(pg_temp.identity_id('package'))->>'created_at')~'Z$','Canonical immutable timestamps use UTC');
select is((select count(*)from inventory_movements),0::bigint,'Metadata never receives/dispenses stock');
select is((select count(*)from billing_invoices),0::bigint,'Metadata never bills');
select is((select count(*)from communication_outbox),0::bigint,'Metadata never queues communications');
set constraints all immediate;
select *from finish();
rollback;
